import scala.util.Using
final class Document(path: String) extends AutoCloseable {      // the Whole
  private val parts = scala.collection.mutable.ArrayBuffer.empty[Paragraph]
  private val io = new java.io.PrintWriter(path)                // owned resource
  def add(text: String): Paragraph = { val p = Paragraph(text); parts += p; p }
  override def close(): Unit = { parts.foreach(_.close()); io.close() }
}
Using.resource(new Document("a.txt")) { doc => doc.add("hello") }
